      "fr": "ANDRÉ : Elle était avec ce Robert Chanteuil... Il paraît qu'il est très assidu au tennis, cet été. [Il aurait l’intention de se fixer définitivement par ici, même de se marier.",
      "en": "ANDRÉ: Elle était avec ce Robert Chanteuil... Il paraît qu'il est très assidu au tennis, cet été. [Il aurait l’intention de se fixer définitivement par ici, même de se marier."
