      "en": "OCTAVE: J’en serais surpris, elles n’auront que des dots insignifiantes, et 1l doit avoir de grosses exigences. pers nnage me Doit peu intéressant, et je étonnée que ses faits et gestes t” occupent | point. ons — Mais, ma tante..."
