      "fr": "ALINE : Raymond t’avait dit quelque chose? MrreizLe, bas, à André, d’unton suppliant. — À quoi bon, à présent?",
      "en": "ALINE: Raymond t’avait dit quelque chose? MrreizLe, bas, à André, d’unton suppliant. — À quoi bon, à présent?"
