      "fr": "MIREILLE : Quand on est indispensable aux autres de cette façon-là... je ne sais pas, on n’est plus libre... on ne... on ne respire 44 LA CHAPELLE ARDENTE plus. ( Apec effroi.) Ah! qu ’est-ce que je dis? Non, ce n’est pas ça; ce n’est pas ça... Vous ne comprenez pas.",
      "en": "MIREILLE: Quand on est indispensable aux autres de cette façon-là... I do not know, on n’est plus libre... on ne... on ne respire 44 The funeral chapel plus. ( Apec effroi.) Ah! qu ’est-ce que je dis? Non, ce n’est pas ça; ce n’est pas ça... Vous ne comprenez pas."
