      "en": "ALINE: Il a toujours été très préoccupé de sa santé ; je ne lui en fais pas un crime; pm nes a ne ES cle 46 The funeral chapel c’est un garçon très frêle... Bien qu'il exagérât quelquefois un peu “les précautions. Raymond le plaisantait souvent à ce propos."
