      "fr": "ALINE : Laisse-moi finir, veux-tu ; c’est grave, je t'assure. [l ne faut pas que ce soit simplement un mot tendre, mais mensonger ; il faut que ce soit la vérité de ton cœur.",
      "en": "ALINE: Laisse-moi finir, veux-tu ; c’est grave, je t'assure. [l ne faut pas que ce soit simplement un mot tendre, mais mensonger ; il faut que ce soit la vérité de ton cœur."
